// MARKT-WATCHLIST LADEN
// Gibt Marktindizes, Währungen und Rohstoffe als Items aus.
const watchlist = [
  { symbol: '^GDAXI',   name: 'DAX',             markt_typ: 'index',    region: 'Deutschland', waehrung: 'EUR',     referenz_fuer: 'SAP.DE,SIE.DE,BASF.DE,ALV.DE,MBG.DE,BMW.DE,VOW3.DE,DBK.DE,DTE.DE,RWE.DE,BAYN.DE,EOAN.DE,ADS.DE,HEN3.DE,FRE.DE' },
  { symbol: '^MDAXI',   name: 'MDAX',            markt_typ: 'index',    region: 'Deutschland', waehrung: 'EUR',     referenz_fuer: 'deutsche_nebenwerte' },
  { symbol: '^STOXX50E',name: 'Euro Stoxx 50',   markt_typ: 'index',    region: 'Europa',      waehrung: 'EUR',     referenz_fuer: 'europa' },
  { symbol: '^IXIC',    name: 'Nasdaq Composite',markt_typ: 'index',    region: 'USA',         waehrung: 'USD',     referenz_fuer: 'technologie' },
  { symbol: '^GSPC',    name: 'S&P 500',         markt_typ: 'index',    region: 'USA',         waehrung: 'USD',     referenz_fuer: 'global' },
  { symbol: 'EURUSD=X', name: 'EUR/USD',         markt_typ: 'waehrung', region: 'FX',          waehrung: 'EUR/USD', referenz_fuer: 'export_import' },
  { symbol: 'CL=F',     name: 'WTI Öl',          markt_typ: 'rohstoff', region: 'global',      waehrung: 'USD',     referenz_fuer: 'energie_inflation' },
  { symbol: 'GC=F',     name: 'Gold',            markt_typ: 'rohstoff', region: 'global',      waehrung: 'USD',     referenz_fuer: 'risk_off' }
];
const _startedAt = new Date().toISOString();
return watchlist.map(s => ({ json: { ...s, _run_started_at: _startedAt } }));

// MARKTANALYSE BERECHNEN
// Modus: runOnceForEachItem
// Gleiche Logik wie Technische Analyse, aber ohne Handelsbewertung.
// Ziel: Markt­status (risk_on / risk_off / neutral) für Kontextualisierung.

const input  = $input.item.json;
const meta_w = $('Markt-Watchlist laden').item.json;

const symbol       = meta_w.symbol       || input.symbol       || '';
const name         = meta_w.name         || '';
const markt_typ    = meta_w.markt_typ    || '';
const region       = meta_w.region       || '';
const waehrung     = meta_w.waehrung     || '';
const referenz_fuer = meta_w.referenz_fuer || '';

const heute      = new Date().toISOString().substring(0, 10);
const zeitstempel = new Date().toISOString();

const fehlObj = (msg) => ({ json: {
  symbol, name, markt_typ, region, waehrung, referenz_fuer,
  datum: heute, zeitstempel, type: 'market_context',
  aktueller_kurs: null, veraenderung_abs: null, veraenderung_pct: null,
  rsi: null, rsi_signal: '', macd: null, macd_signal_linie: null,
  macd_histogramm: null, macd_signal: '', trend: '', ema20: null,
  bb_oben: null, bb_mitte: null, bb_unten: null, kurs_bei_bollinger: '',
  signal_punkte: 0, signal_gruende: '', signal_staerke: '',
  markt_status: 'unbekannt', risk_level: 'unbekannt', markt_hinweis: msg,
  quelle: 'Yahoo Finance', status: 'fehler', fehler: msg
}});

try {
  if (!input.chart?.result?.[0]) return fehlObj('Keine Chartdaten');
  const chart = input.chart.result[0];
  const meta  = chart.meta || {};
  const quote = chart.indicators?.quote?.[0];
  if (!quote) return fehlObj('Keine Quote-Daten');

  // FIX 2026-08-01 (Fehleranalyse C4/C5, kritisch): die alte Fassung filterte "closes" separat
  // von rawOpen/rawHigh/rawLow/rawVolume - bei einem an einem einzelnen Tag fehlenden Wert
  // (z.B. close=null waehrend die Session noch nicht abgeschlossen ist) verschoben sich die
  // unabhaengig gefilterten/indizierten Arrays gegeneinander: kerze_close (aus "closes",
  // Vortag) und kerze_open/high/low/volume (roh, aktueller/ausgefallener Tag) konnten dadurch
  // aus zwei verschiedenen Handelstagen stammen. Jetzt dieselbe timestamp-indizierte
  // Kerzenbildung + Zeilenpruefung wie in "02" (Node "Technische Analyse (RSI/MACD/BB)") -
  // eine Kerze ist ab hier eine untrennbare Einheit.
  const rawTimestamps = chart.timestamp || [];
  const rawOpen = quote.open || [];
  const rawHigh = quote.high || [];
  const rawLow = quote.low || [];
  const rawClose = quote.close || [];
  const rawVolume = quote.volume || [];

  const n0 = rawTimestamps.length;
  const rohKerzen = [];
  for (let i = 0; i < n0; i++) {
    rohKerzen.push({
      ts: rawTimestamps[i],
      open: rawOpen[i] != null ? Number(rawOpen[i]) : null,
      high: rawHigh[i] != null ? Number(rawHigh[i]) : null,
      low: rawLow[i] != null ? Number(rawLow[i]) : null,
      close: rawClose[i] != null ? Number(rawClose[i]) : null,
      volume: rawVolume[i] != null ? Number(rawVolume[i]) : null
    });
  }

  // Duplikate/unsortierte Zeitstempel defensiv bereinigen (letzter Wert je Zeitstempel
  // gewinnt, aufsteigend sortiert) - identisches Muster wie in "02".
  const byTs = new Map();
  for (const k of rohKerzen) if (k.ts != null) byTs.set(k.ts, k);
  const kerzenSortiert = Array.from(byTs.values()).sort((a, b) => a.ts - b.ts);

  function kerzePruefen(k) {
    const issues = [];
    if (k.close == null || isNaN(k.close)) issues.push('close_fehlt');
    if (k.high == null || k.low == null) issues.push('high_oder_low_fehlt');
    if (k.high != null && k.low != null && k.high < k.low) issues.push('high_kleiner_low');
    if (k.open != null && k.high != null && k.low != null && (k.open > k.high || k.open < k.low)) issues.push('open_ausserhalb_high_low');
    if (k.close != null && k.high != null && k.low != null && (k.close > k.high || k.close < k.low)) issues.push('close_ausserhalb_high_low');
    if (k.volume != null && k.volume < 0) issues.push('negatives_volumen');
    return issues;
  }

  const gueltigeKerzen = [];
  let ungueltigeZeilen = 0;
  for (const k of kerzenSortiert) {
    const issues = kerzePruefen(k);
    if (issues.length === 0) gueltigeKerzen.push(k); else ungueltigeZeilen++;
  }

  const closes = gueltigeKerzen.map(k => k.close);
  if (closes.length < 26) return fehlObj(`Zu wenige Datenpunkte (${closes.length})`);

  // Kerze mit dem juengsten Zeitstempel - alle fuenf Felder stammen jetzt garantiert aus
  // demselben Handelstag (siehe FIX-Kommentar oben).
  const letzteKerze = gueltigeKerzen[gueltigeKerzen.length - 1];
  const letzterOpen = letzteKerze.open;
  const letzterHigh = letzteKerze.high;
  const letzterLow = letzteKerze.low;
  const letztesVolumen = letzteKerze.volume;
  const letzterTimestamp = letzteKerze.ts;
  // FIX 2026-08-01 (Fehleranalyse C5): echter Datenqualitaetsstatus statt hartcodiertem
  // 'limited' in "Kurshistorie: SQL bauen" - dort ausgewertet ueber dieses Feld.
  const dataQualityStatus = ungueltigeZeilen > 0 ? 'limited' : 'valid';

  const aktKurs  = closes[closes.length - 1];
  const vorKurs  = closes[closes.length - 2];
  const veraAbs  = parseFloat((aktKurs - vorKurs).toFixed(4));
  const veraPct  = parseFloat(((aktKurs - vorKurs) / vorKurs * 100).toFixed(2));

  // EMA-Hilfsfunktionen
  function ema(arr, p) {
    if (arr.length < p) return null;
    const k = 2 / (p + 1);
    let e = arr.slice(0, p).reduce((a, b) => a + b, 0) / p;
    for (let i = p; i < arr.length; i++) e = arr[i] * k + e * (1 - k);
    return e;
  }
  function emaSeries(arr, p) {
    if (arr.length < p) return [];
    const k = 2 / (p + 1);
    const res = [];
    let e = arr.slice(0, p).reduce((a, b) => a + b, 0) / p;
    for (let i = 0; i < arr.length; i++) {
      if (i < p - 1) res.push(null);
      else if (i === p - 1) res.push(e);
      else { e = arr[i] * k + e * (1 - k); res.push(e); }
    }
    return res;
  }
  function rsi14(arr) {
    if (arr.length <= 14) return null;
    let g = 0, l = 0;
    for (let i = arr.length - 14; i < arr.length; i++) {
      const d = arr[i] - arr[i - 1];
      if (d > 0) g += d; else l += Math.abs(d);
    }
    const ag = g / 14, al = l / 14;
    return al === 0 ? 100 : 100 - (100 / (1 + ag / al));
  }
  const r = (v, d = 2) => v == null || isNaN(v) ? null : parseFloat(v.toFixed(d));

  // RSI
  const rsiVal    = r(rsi14(closes), 1);
  const rsiSignal = rsiVal == null ? '' :
    rsiVal < 25 ? 'STARK ÜBERVERKAUFT' : rsiVal < 35 ? 'Überverkauft' :
    rsiVal > 75 ? 'STARK ÜBERKAUFT'    : rsiVal > 65 ? 'Überkauft' : 'Neutral';

  // MACD
  const ema12S = emaSeries(closes, 12);
  const ema26S = emaSeries(closes, 26);
  const macdFull = closes.map((_, i) =>
    ema12S[i] != null && ema26S[i] != null ? ema12S[i] - ema26S[i] : null
  ).filter(v => v != null);

  if (macdFull.length < 9) return fehlObj('MACD-Datenbasis zu gering');

  const sigS    = emaSeries(macdFull, 9).filter(v => v != null);
  const macdV   = macdFull[macdFull.length - 1];
  const macdSig = sigS[sigS.length - 1];
  const macdHist = r(macdV - macdSig);

  let macdSignal = 'Neutral';
  const macdPrev = macdFull[macdFull.length - 2];
  const sigPrev  = sigS[sigS.length - 2];
  if (macdPrev <= sigPrev && macdV > macdSig) macdSignal = 'Bullische Kreuzung';
  else if (macdPrev >= sigPrev && macdV < macdSig) macdSignal = 'Bärische Kreuzung';
  else if (macdV > macdSig) macdSignal = 'Bullisch';
  else if (macdV < macdSig) macdSignal = 'Bärisch';

  // EMA20 / Trend
  const ema20V  = r(ema(closes, 20));
  const aufwaerts = aktKurs > ema20V;

  // Welle 2, AP3: EMA200 (falls genug Historie vorhanden - period=1y liefert ~252
  // Tage, EMA200 ist damit knapp aber verlaesslich berechenbar; bei weniger als
  // 200 Tagen bleibt sie explizit NULL statt eines Naeherungswerts).
  const ema200V = closes.length >= 200 ? r(ema(closes, 200)) : null;
  const ueberEma200 = ema200V !== null ? aktKurs > ema200V : null;

  // Bollinger
  const bb20  = closes.slice(-20);
  const bbAvg = bb20.reduce((a, b) => a + b, 0) / 20;
  const bbStd = Math.sqrt(bb20.map(p => (p - bbAvg) ** 2).reduce((a, b) => a + b, 0) / 20);
  const bbO   = r(bbAvg + 2 * bbStd);
  const bbU   = r(bbAvg - 2 * bbStd);
  const bbPos = aktKurs >= bbO * 0.995 ? 'oben' : aktKurs <= bbU * 1.005 ? 'unten' : 'mitte';

  // Signal-Punkte (vereinfacht)
  let punkte = 0;
  const gruende = [];
  if (rsiVal != null) {
    if (rsiVal < 25 || rsiVal > 75) { punkte += 3; gruende.push('RSI extrem'); }
    else if (rsiVal < 35 || rsiVal > 65) { punkte += 2; gruende.push('RSI stark'); }
  }
  if (macdSignal.includes('Kreuzung')) { punkte += 3; gruende.push(`MACD ${macdSignal}`); }
  else if (macdSignal !== 'Neutral') { punkte += 1; gruende.push(`MACD ${macdSignal}`); }
  if (bbPos !== 'mitte') { punkte += 2; gruende.push(`Bollinger ${bbPos}`); }

  const signalStaerke = punkte >= 6 ? 'hoch' : punkte >= 3 ? 'mittel' : 'niedrig';

  // markt_status
  const macdBullisch = macdSignal === 'Bullisch' || macdSignal === 'Bullische Kreuzung';
  const macdBaerisch = macdSignal === 'Bärisch'  || macdSignal === 'Bärische Kreuzung';

  let markt_status, risk_level, markt_hinweis;

  if (aufwaerts && macdBullisch && veraPct >= -0.5) {
    markt_status = 'risk_on';
    risk_level   = veraPct >= 0.5 ? 'niedrig' : 'mittel';
    markt_hinweis = `${name} über EMA20, MACD bullisch. Tagesveränderung ${veraPct}%.`;
  } else if (!aufwaerts && macdBaerisch && veraPct <= -1.0) {
    markt_status = 'risk_off';
    risk_level   = veraPct <= -2.0 ? 'hoch' : 'mittel';
    markt_hinweis = `${name} unter EMA20, MACD bärisch. Tagesveränderung ${veraPct}%.`;
  } else if (!aufwaerts && veraPct <= -1.0) {
    markt_status = 'risk_off';
    risk_level   = 'mittel';
    markt_hinweis = `${name} unter EMA20 mit negativer Tagesperformance (${veraPct}%).`;
  } else if (aufwaerts && veraPct >= 0.5) {
    markt_status = 'risk_on';
    risk_level   = 'niedrig';
    markt_hinweis = `${name} über EMA20, positive Performance (${veraPct}%).`;
  } else {
    markt_status = 'neutral';
    risk_level   = 'niedrig';
    markt_hinweis = `${name} zeigt keine klare Richtung. Tagesveränderung ${veraPct}%.`;
  }

  return { json: {
    symbol, name, markt_typ, region, waehrung, referenz_fuer,
    datum: heute, zeitstempel, type: 'market_context',
    aktueller_kurs:    r(aktKurs, 4),
    veraenderung_abs:  veraAbs,
    veraenderung_pct:  veraPct,
    rsi:               rsiVal,
    rsi_signal:        rsiSignal,
    macd:              r(macdV),
    macd_signal_linie: r(macdSig),
    macd_histogramm:   macdHist,
    macd_signal:       macdSignal,
    trend:             aufwaerts ? 'Aufwärts' : 'Abwärts',
    ema20:             ema20V,
    bb_oben:           bbO,
    bb_mitte:          r(bbAvg),
    bb_unten:          bbU,
    kurs_bei_bollinger: bbPos,
    signal_punkte:     punkte,
    signal_gruende:    gruende.join(', '),
    signal_staerke:    signalStaerke,
    markt_status,
    risk_level,
    markt_hinweis,
    ema200: ema200V,
    ueber_ema200: ueberEma200,
    closes_json: JSON.stringify(closes),
    kerze_open: letzterOpen,
    kerze_high: letzterHigh,
    kerze_low: letzterLow,
    kerze_close: aktKurs,
    kerze_volume: letztesVolumen,
    kerze_timestamp: letzterTimestamp,
    data_quality_status: dataQualityStatus,
    quelle: 'Yahoo Finance',
    status: 'ok',
    fehler: ''
  }};
} catch(e) {
  return fehlObj(e.message);
}

const dbRows = $input.all().map(i => i.json || {});
const marktItems = $('Marktanalyse berechnen').all().map(i => i.json || {});

const foundBySymbol = {};
for (const row of dbRows) {
  const symbol = String(row.symbol || '').trim();
  const hasId = row.id !== undefined && row.id !== null && String(row.id).trim() !== '';
  if (symbol && hasId) foundBySymbol[symbol] = row;
}

return marktItems.map(markt => {
  const symbol = String(markt.symbol || '').trim();
  const found = foundBySymbol[symbol];
  const rowExists = found !== undefined && found.id !== undefined && found.id !== null && String(found.id).trim() !== '';
  return {
    json: {
      ...markt,
      _existing_id: rowExists ? String(found.id) : '',
      _rowExists: Boolean(rowExists)
    }
  };
});

function pgStr(v) { return v === null || v === undefined || v === '' ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }

// Welle 1, AP1 (2026-07-31): $json ist der Rueckgabewert von "DB: Marktumfeld
// aktualisieren"/"neu anlegen" (Data-Table-Node, nur eigene Spalten) - die
// neuen OHLCV-Rohwerte existieren dort nicht. Direkt aus "Marktanalyse
// berechnen" nachladen (.all()+Symbol-Matching, kein .item).
function sourceFor(symbol) {
  try {
    const all = $('Marktanalyse berechnen').all();
    const match = all.find(i => i.json && i.json.symbol === symbol);
    return match ? match.json : {};
  } catch (e) { return {}; }
}
const outer = $json;
const j = sourceFor(outer.symbol);

if (j.kerze_close === undefined || j.kerze_close === null || j.kerze_close === '' || isNaN(Number(j.kerze_close))) {
  return { json: { ...outer, sql: 'SELECT 1;' } };
}

const tradingDate = j.datum;
const sourceTs = j.kerze_timestamp ? new Date(Number(j.kerze_timestamp) * 1000).toISOString() : null;

// Point-in-Time-Revisionierung wie in "02" (sql/025) - kein ON CONFLICT DO
// UPDATE mehr, das bisher jeden Vortageswert kommentarlos ueberschrieben hat.
// exchange bleibt NULL: 02b-Symbole (Indizes/FX wie ^GDAXI, EURUSD=X) haben
// keinen trading.stock_instruments-Eintrag.
const sql = `UPDATE trading.stock_price_history
  SET valid_to = now()
  WHERE symbol = ${pgStr(j.symbol)} AND trading_date = ${pgStr(tradingDate)} AND valid_to IS NULL;

INSERT INTO trading.stock_price_history
  (symbol, trading_date, open, high, low, close, volume, currency, source, source_timestamp, data_quality_status, revision_number)
  SELECT ${pgStr(j.symbol)}, ${pgStr(tradingDate)}, ${pgNum(j.kerze_open)}, ${pgNum(j.kerze_high)}, ${pgNum(j.kerze_low)}, ${pgNum(j.kerze_close)}, ${pgNum(j.kerze_volume)}, ${pgStr(j.waehrung)}, 'marktumfeld-02b', ${pgStr(sourceTs)}, ${pgStr(j.data_quality_status || 'limited')},
    COALESCE((SELECT MAX(revision_number) FROM trading.stock_price_history WHERE symbol = ${pgStr(j.symbol)} AND trading_date = ${pgStr(tradingDate)}), 0) + 1;`;
return { json: { ...outer, sql } };

const items = $input.all().map(i => i.json).filter(i => i.symbol !== undefined);
const total = items.length;
const errorItems = items.filter(i => i.status === 'fehler' || i.fehler);
const successful = total - errorItems.length;
const failed = errorItems.length;

let status;
if (total === 0) status = 'skipped';
else if (failed === 0) status = 'success';
else if (successful === 0) status = 'failed';
else status = 'partial_failure';

let startedAt = null;
try { startedAt = $('Markt-Watchlist laden').all()[0].json._run_started_at; } catch (e) {}
let runId = null;
try { runId = $('Execute Workflow Trigger').all()[0].json.context.run_id; } catch (e) {}

return [{ json: {
  ok: failed === 0,
  workflow: '02b \u2013 Marktumfeld t\u00e4glich',
  run_id: runId,
  processed: total,
  successful,
  failed,
  warnings: [],
  errors: errorItems.map(i => ({ ticker: i.symbol, node: 'Markt-Kursdaten abrufen (lokaler FastAPI)', message: i.fehler || 'Unbekannter Fehler' })),
  started_at: startedAt,
  finished_at: new Date().toISOString(),
  status
} }];

// Welle 2, AP3: Marktregime aus den 8 Referenzsymbolen ableiten (deterministisch,
// keine KI, keine erfundene Marktbreite/Liquiditaet - beide bleiben 'not_available',
// da keine Datenquelle dafuer existiert). Laeuft einmal je Lauf (runOnceForAllItems),
// liest die vollstaendigen Ergebnisse aus "Marktanalyse berechnen" per Namenszugriff
// (nicht ueber die aktuelle Item-Kette, da diese durch die Data-Table-Nodes bereits
// auf deren eigene Spalten reduziert sein kann).
const RULE_VERSION = 'regime-v2';

// Folgeauftrag (2026-08-01): bereits von "03" klassifizierte marktweite/makro-
// oekonomische Nachrichten (wirkungsebene IN ('markt','makro')) fliessen jetzt
// zusaetzlich in stress_regime ein - vorher wurde nur Kurs-/Volatilitaetsdaten
// der 8 Referenzsymbole genutzt, obwohl "03" diese Einstufung laengst liefert.
// Dieselbe Nachrichtenlage gilt fuer Europa UND USA (deutsche Wirtschaftsmedien
// berichten ueber EZB und Fed gleichermassen, keine Regionstrennung in den
// Nachrichtendaten vorhanden - bewusste Vereinfachung).
const makroNewsRows = $('DB: Markt-/Makro-News heute laden').all().map(i => i.json || {}).filter(j => j.titel);
const makroNewsNegativHoch = makroNewsRows.filter(n => n.wirkungsrichtung === 'negativ' && n.wirkung_staerke === 'hoch');
const makroNewsSignal = {
  anzahl_gesamt: makroNewsRows.length,
  anzahl_negativ_hoch: makroNewsNegativHoch.length,
  titel_negativ_hoch: makroNewsNegativHoch.map(n => n.titel).slice(0, 5)
};
const alle = $('Marktanalyse berechnen').all().map(i => i.json || {}).filter(a => a.status === 'ok');
function find(sym) { return alle.find(a => a.symbol === sym) || null; }

function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit' }).format(date);
}
const heute = getBusinessDate();

function realizedVol20(closesJson) {
  let closes;
  try { closes = JSON.parse(closesJson || '[]'); } catch (e) { return null; }
  if (!closes || closes.length < 21) return null;
  const recent = closes.slice(-21);
  const returns = [];
  for (let i = 1; i < recent.length; i++) if (recent[i - 1] > 0) returns.push(Math.log(recent[i] / recent[i - 1]));
  if (returns.length < 20) return null;
  const mean = returns.reduce((a, b) => a + b, 0) / returns.length;
  const variance = returns.reduce((a, b) => a + (b - mean) * (b - mean), 0) / (returns.length - 1);
  return Math.sqrt(variance) * Math.sqrt(252);
}

function sessionStatusFor(tz, openStr, closeStr) {
  const now = new Date();
  const parts = new Intl.DateTimeFormat('en-GB', { timeZone: tz, hour: '2-digit', minute: '2-digit', hour12: false, weekday: 'short' }).formatToParts(now);
  const hh = parts.find(p => p.type === 'hour').value;
  const mm = parts.find(p => p.type === 'minute').value;
  const wd = parts.find(p => p.type === 'weekday').value;
  const timeStr = hh + ':' + mm;
  if (['Sat', 'Sun'].includes(wd)) return 'holiday';
  if (timeStr < openStr) return 'closed_complete';
  if (timeStr < closeStr) return 'open_intraday';
  return 'closed_complete';
}

function regionRegime(region, symbols, tz, openStr, closeStr) {
  const rows = symbols.map(find).filter(r => r !== null);
  const sessionStatus = sessionStatusFor(tz, openStr, closeStr);
  if (rows.length === 0) {
    return {
      region, trend_regime: 'unknown', volatility_regime: 'unknown', breadth_regime: null,
      stress_regime: 'unknown', liquidity_regime: null, combined_regime: 'unknown',
      regime_confidence: 0, data_quality: 'invalid', session_status: sessionStatus, inputs: { symbols_erwartet: symbols, symbols_verfuegbar: [] }
    };
  }
  const trendVotes = rows.map(r => r.trend === 'Aufwärts');
  const bullShare = trendVotes.filter(Boolean).length / trendVotes.length;
  const trendRegime = bullShare >= 0.5 ? 'bull' : 'bear';

  const ema200Rows = rows.filter(r => r.ueber_ema200 !== null && r.ueber_ema200 !== undefined);
  const ema200BullShare = ema200Rows.length > 0 ? ema200Rows.filter(r => r.ueber_ema200).length / ema200Rows.length : null;

  const vols = rows.map(r => realizedVol20(r.closes_json)).filter(v => v !== null);
  const avgVol = vols.length > 0 ? vols.reduce((a, b) => a + b, 0) / vols.length : null;
  const volRegime = avgVol === null ? 'unknown' : (avgVol > 0.30 ? 'high_vol' : 'low_vol');

  const riskOffShare = rows.filter(r => r.markt_status === 'risk_off').length / rows.length;
  // Stress gilt jetzt auch bei mindestens einer stark negativen Markt-/Makro-
  // Nachricht desselben Tages, unabhaengig von der Kurs-/Volatilitaetslage -
  // eine EZB-Zinsschock-Meldung kann Stress ausloesen, bevor sich das in den
  // Tageskursen der Referenzindizes niederschlaegt.
  const stressRegime = (avgVol !== null && avgVol > 0.45 && riskOffShare >= 0.5) || makroNewsSignal.anzahl_negativ_hoch >= 1 ? 'stress' : 'none';

  let combined;
  if (stressRegime === 'stress') combined = 'stress';
  else if (trendRegime === 'bear' && bullShare <= 0.3) combined = 'bear_trend';
  else if (trendRegime === 'bull' && volRegime === 'low_vol') combined = 'bull_trend_low_vol';
  else if (trendRegime === 'bull' && volRegime === 'high_vol') combined = 'bull_trend_high_vol';
  else if (volRegime === 'low_vol') combined = 'sideways_low_vol';
  else if (volRegime === 'high_vol') combined = 'sideways_high_vol';
  else combined = 'unknown';

  const confidence = Math.min(1, rows.length / symbols.length) * (avgVol !== null ? 1 : 0.5);

  return {
    region, trend_regime: trendRegime, volatility_regime: volRegime, breadth_regime: null,
    stress_regime: stressRegime, liquidity_regime: null, combined_regime: combined,
    regime_confidence: Math.round(confidence * 100) / 100,
    data_quality: rows.length === symbols.length ? 'valid' : 'limited',
    session_status: sessionStatus,
    inputs: {
      symbols_erwartet: symbols, symbols_verfuegbar: rows.map(r => r.symbol),
      avg_realized_vol_20d: avgVol !== null ? Math.round(avgVol * 10000) / 10000 : null,
      bull_share: Math.round(bullShare * 100) / 100, ema200_bull_share: ema200BullShare, risk_off_share: Math.round(riskOffShare * 100) / 100,
      makro_news: makroNewsSignal
    }
  };
}

const europa = regionRegime('Europa', ['^GDAXI', '^STOXX50E'], 'Europe/Berlin', '09:00', '17:30');
