  }
};

return [europa, usa, global].map(r => ({ json: { ...r, business_date: heute, rule_version: RULE_VERSION } }));

function pgStr(v) { return v === null || v === undefined || v === '' ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgJsonb(v) { return (v === null || v === undefined) ? "'{}'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }

const j = $json;
const sql = `INSERT INTO trading.market_regime
  (region, business_date, trend_regime, volatility_regime, breadth_regime, stress_regime, liquidity_regime, combined_regime, regime_confidence, data_quality, session_status, inputs_json, rule_version)
  VALUES (${pgStr(j.region)}, ${pgStr(j.business_date)}, ${pgStr(j.trend_regime)}, ${pgStr(j.volatility_regime)}, ${pgStr(j.breadth_regime)}, ${pgStr(j.stress_regime)}, ${pgStr(j.liquidity_regime)}, ${pgStr(j.combined_regime)}, ${pgNum(j.regime_confidence)}, ${pgStr(j.data_quality)}, ${pgStr(j.session_status)}, ${pgJsonb(j.inputs)}, ${pgStr(j.rule_version)})
  ON CONFLICT (region, business_date) DO UPDATE SET
    trend_regime = EXCLUDED.trend_regime, volatility_regime = EXCLUDED.volatility_regime,
    breadth_regime = EXCLUDED.breadth_regime, stress_regime = EXCLUDED.stress_regime,
    liquidity_regime = EXCLUDED.liquidity_regime, combined_regime = EXCLUDED.combined_regime,
    regime_confidence = EXCLUDED.regime_confidence, data_quality = EXCLUDED.data_quality,
    session_status = EXCLUDED.session_status, inputs_json = EXCLUDED.inputs_json,
    rule_version = EXCLUDED.rule_version, known_at = now();`;
return { json: { ...j, sql } };
